    translate([-length_x / 2, 0, 0])
        rotate([90, 0, 0])
            linear_extrude(height = length_x)
                polygon(points = [
                    // Bottom flange: x = -7 to 7, y = -7 to 7
                    for (sx = [-7, 7], sy = [-7, 7])
                        [sx, sy, 0],
                    // Neck: x = -3.5 to 3.5, y = -3.5 to 3.5, z = 2.5 to 5.5
                    for (sx = [-3.5, 3.5], sy = [-3.5, 3.5])
                        [sx, sy, neck_top_z]
                ]);

    // Vertical screw hole through the centre of the part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_top_z + 2 * eps);
}
