rim_z          = bottom_z + outer_radius;  // mm, z of the rim (12)

// ---- Handle ----
handle_length = 82;    // mm, handle runs from x = 10 to x = 92
handle_width  = 12;    // mm, handle width along Y
handle_thick  = 3;     // mm, handle thickness (z = 9 to 12), flush with rim
overlap       = 0.5;   // mm, handle extends into the rim for a solid union

difference() {
    union() {
        // Hollow spherical bowl: lower half of a sphere, open top
        cylinder(r = outer_radius, h = outer_radius, $fn = 128);

        // Flat handle along +X, centred on y = 0
        translate([10, -handle_width / 2, bottom_z + outer_radius - handle_thick])
            cube([handle_length, handle_width, handle_thick]);
    }

    // Remove the lower half of the interior (above z = bottom_z) to create the pocket
    translate([0, 0, bottom_z])
        cylinder(r = outer_radius - wall_thickness, h = outer_radius + 1, $fn = 128);
