// Powder measuring scoop
// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
bowl_outer_radius   = 15;    // outer radius of spherical bowl (mm)
bowl_wall_thickness = 2;     // wall thickness of bowl (mm)
handle_width       = 12;    // handle width along Y (mm)
handle_thickness   = 3;     // handle thickness along Z (mm)
handle_start_x     = 13;    // handle start position along X (mm)
handle_end_x       = 75;    // handle end position along X (mm)
cut_extra          = 0.5;   // extra length on cutters to avoid coplanar faces (mm)

$fn = 96;                   // curve resolution

// Derived values
bowl_inner_radius = bowl_outer_radius - bowl_wall_thickness;
handle_top_z      = handle_thickness + 15;   // top face of handle (flush with rim)

// ---------------- Model ----------------
union() {
    // Hollow spherical bowl: lower half only, opens upward
    difference() {
        translate([0, 0, 15])
            sphere(r = bowl_outer_radius);
        translate([0, 0, 15 - cut_extra])
            sphere(r = bowl_inner_radius);
    }
    // Keep only the lower half of the sphere (z = 0 to z = 15)
    translate([0, 0, -cut_extra])
        difference() {
            sphere(r = bowl_outer_radius);
            translate([0, 0, cut_extra])
                cube([bowl_outer_radius * 2, bowl_outer_radius * 2, cut_extra]);
        }
    // Combine with the upper half that was not deleted
    translate([0, 0, 15 - cut_extra])
        sphere(r = bowl_outer_radius);
}

// Flat handle running along +X, centred on y = 0
// Top face flush with the rim at z = 15
translate([handle_start_x, -handle_width / 2, 15 - handle_thickness])
    cube([handle_end_x - handle_start_x, handle_width, handle_thickness]);
