tunnel_count = 3;     // number of tunnels
tunnel_pitch = 16;    // centre-to-centre spacing of tunnels along X (mm)

eps          = 0.5;   // overcut so cutters pass beyond the faces they cut

$fn = 96;             // curve resolution

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_h]);

    // Tunnels: cylinder axes along Y, centred along X
    for (i = [0 : tunnel_count - 1]) {
        x = (i - (tunnel_count - 1)/2) * tunnel_pitch;
        translate([x, 0, 0])
            rotate([90, 0, 0])
                cylinder(d = tunnel_d, h = block_wid + 2*eps, center = true);
    }
}
