knuckle_y   = plate_wid/2;   // knuckle axis Y (on +Y edge)
knuckle_z   = 3.5;    // knuckle axis height above bed
pin_d       = 3;      // pin hole diameter

// ---- Helpers ----
eps         = 0.5;   // cutter overshoot past faces
pitch       = plate_len/knuckle_n; // 10 mm segment length
select      = [0, 2, 4]; // 1st, 3rd, 5th segments (0-indexed)

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders, axis along X at specified Y and Z
        for (i = select)
            translate([knuckle_x0 + i*pitch, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_len);
    }

    // Pin hole running along the knuckle axis through every knuckle
    translate([knuckle_x0, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps, center = true);
}
