```openscad
// Leaf of a pin hinge
// Print orientation: flat plate on the bed, knuckles pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 50;    // plate length along X (mm)
plate_wid   = 25;    // plate width along Y (mm)
plate_thk   = 2.5;   // plate thickness along Z (mm)

knuckle_d   = 7;     // knuckle cylinder diameter (mm)
knuckle_z   = 3.5;   // knuckle axis height above bed (mm)
knuckle_n   = 5;     // number of segments along plate length
knuckle_pitch = plate_len / knuckle_n; // segment length (10 mm)
knuckle_hole = 3;    // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------------- Derived ----------------
knuckle_y   = plate_wid / 2;             // knuckle axis Y position (12.5)
knuckle_xs  = [for (i = [0 : 2 : knuckle_n - 1]) i * knuckle_pitch]; // 1st, 3rd, 5th segment centres

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles: cylinders whose axes run along X at y = 12.5, z = 3.5
    for (x = knuckle_xs)
