        translate([offset_x, 0, 0])
            cylinder(d = cam_d, h = cam_t);

        // Central hub (overlaps the disc for a solid union)
        translate([0, 0, cam_t - 0.01])
            cylinder(d = hub_d, h = hub_h + 0.01);
    }

    // Shaft hole through hub and disc
        translate([0, 0, -eps])
            cylinder(d = shaft_d, h = cam_t + 2 * eps);
}
