                translate([0, 0, 0])
                    union() {
                        // outer point
                        cylinder(r = outer_r, h = thickness);
                        // inner point
                        translate([0, inner_r, 0])
                            cylinder(r = inner_r, h = thickness);
                    }
        }
    }
    // central hole
    translate([0, 0, -eps])
        cylinder(d = hole, h = thickness + 2 * eps);
}
