    // Solid square frustum with flat sloping sides
    hull() {
        translate([-bottom_w / 2, -bottom_w / 2, bottom_h])
            cube([bottom_w, bottom_w, bottom_h + 1]);  // tiny seed at z = 0
        translate([-top_w / 2, -top_w / 2, top_h])
            cube([top_w, top_w, 1]);                   // tiny seed at z = 30
    }

    // Square pocket centred on the top face, open at the top
    translate([-pocket_w / 2, -pocket_w / 2, top_h - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}
