module profile() {
    linear_extrude(thickness) {
        union() {
            // left grip
            translate([grip_x0, -grip_w / 2, 0])
                cube([grip_len, grip_w, thickness]);
            // right grip
            translate([grip_x1, -grip_w / 2, 0])
                cube([grip_len, grip_w, thickness]);
            // gauge section
            translate([-half_gauge, -gauge_w / 2, 0])
                cube([gauge_len, gauge_w, thickness]);
            // left transition: grip -> gauge
            translate([-(half_gauge + trans_len) / 2, -grip_w / 2, 0])
                linear_extrude(thickness)
                    polygon(points = [
                        [0, grip_w / 2],
                        [trans_len, grip_w / 2],
                        [trans_len, gauge_w / 2],
                        [0, gauge_w / 2]
                    ]);
