specimen_t   = 3;     // thickness (Z)
gauge_w      = 8;     // gauge section width (Y)
gauge_l      = 50;    // gauge section length (X)
grip_w       = 19;    // grip section width (Y)
grip_l       = 35;    // grip section length (X)
transition_l = 15;    // transition section length (X)
total_l      = 150;   // overall length (X)

// Derived
