half_gauge  = gauge_w / 2;
eps         = 0.5;    // cutter overshoot

// Check: 2*grip_l + gauge_l + 2*transition_l = 150
assert(abs(2*grip_l + gauge_l + 2*transition_l - total_l) < 0.001, "Length mismatch");

module dogbone() {
    difference() {
        // Solid body
        union() {
            // Grip sections
            for (sx = [-1, 1])
                translate([sx > 0 ? grip_l - transition_l : -grip_l, -half_grip, 0])
                    cube([grip_l + transition_l, grip_w, specimen_t]);

            // Gauge section
            translate([-gauge_l/2, -half_gauge, 0])
                cube([gauge_l, gauge_w, specimen_t]);

            // Transitions (linear width change)
            for (sx = [-1, 1])
                for (ty = [0, 1])
                    translate([sx * (grip_l - transition_l), ty * (gauge_w - grip_w), 0])
                        linear_extrude(specimen_t)
                            polygon([
                                [0, ty * (gauge_w - grip_w) + grip_w],
                                [transition_l, ty * (gauge_w - grip_w)]
                            ]);
        }

        // Notches at grip/gauge boundaries
        for (x = [grip_l - transition_l, -grip_l + transition_l])
            translate([x, -eps, -eps])
                cube([eps, grip_w + 2*eps, specimen_t + 2*eps]);
    }
