// T-shaped nut for aluminium extrusion slot
// Print orientation: flange on XY plane (z = 0), neck builds upward (+Z)

// ---------------- Parameters ----------------
flange_width   = 12;   // flange width along Y (mm)
flange_thick   = 2.5;  // flange thickness along Z (mm), z = 0 .. 2.5
neck_width     = 7;    // neck width along Y (mm)
neck_top_z     = 5.5;  // top of neck along Z (mm)
screw_d        = 3.4;  // central screw hole diameter (mm)
profile_len    = 12;   // part length along X (mm)
eps            = 0.5;  // cutter overshoot past faces (mm)
$fn            = 64;   // curve resolution

// ---------------- Model ----------------
difference() {
    // T profile: bottom flange + centred neck above it
    union() {
        // Flange: z = 0 to 2.5, y = -6 to 6, x = -6 to 6
        translate([-profile_len/2, -flange_width/2, 0])
            cube([profile_len, flange_width, flange_thick]);

        // Neck: z = 2.5 to 5.5, y = -3.5 to 3.5, x = -6 to 6
        translate([-profile_len/2, -neck_width/2, flange_thick])
            cube([profile_len, neck_width, neck_top_z - flange_thick]);
    }

    // Vertical screw hole through the centre of the part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_top_z + eps);
}
