```openscad
// Flat dial ring with radial tick marks for a rotary stage
// Print orientation: flat on bed, top face (with grooves) facing up

// ---------- Parameters ----------
outer_d      = 70;    // ring outer diameter (mm)
inner_d      = 50;    // ring inner diameter (mm)
thickness    = 5;     // ring thickness (mm)
tick_count   = 36;    // number of radial tick marks
tick_w       = 1;     // tick groove width (mm)
tick_depth   = 1.5;   // tick groove depth (mm)
tick_length  = 3;     // tick groove inward length from outer edge (mm)
eps          = 0.5;   // overcut past faces to avoid coplanar surfaces (mm)

$fn = 128;

// ---------- Model ----------
difference() {
    // Main ring body
    cylinder(d = outer_d, h = thickness);

    // Central bore
    translate([0, 0, -eps])
        cylinder(d = inner_d, h = thickness + 2 * eps);

    // Radial tick grooves, first on +X axis
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, i * 360 / tick_count])
            translate([outer_d / 2 - tick_length, 0, thickness - tick_depth])
                cube([tick_length, tick_w, tick_depth + eps]);
    }
}
```

