// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_length   = 50;    // plate length along X (mm)
plate_width    = 20;    // plate width along Y (mm)
plate_thick    = 3;     // plate thickness along Z (mm)

knuckle_count  = 5;     // number of segments along the edge
knuckle_pitch  = 10;    // length of each segment (mm)
knuckle_dia    = 6;     // knuckle cylinder diameter (mm)
knuckle_axis_y = 10;    // Y position of knuckle axis (mm)
knuckle_axis_z = 3;     // Z position of knuckle axis (mm)

pin_dia        = 3;     // pin hole diameter (mm)

eps            = 0.5;   // cutter overshoot past faces (mm)
$fn            = 96;    // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_length/2, -plate_width/2, 0])
            cube([plate_length, plate_width, plate_thick]);

        // Knuckles on the +Y edge: 1st, 3rd, 5th segments
        for (i = [0 : knuckle_count - 1]) {
            if (i % 2 == 0) {
                translate([-knuckle_pitch*i/2 + knuckle_pitch/4,
                           knuckle_axis_y,
                           knuckle_axis_z])
                    cylinder(d = knuckle_dia, h = plate_thick + 2*eps);
            }
        }
    }

    // Pin hole running along X through every knuckle
    translate([-knuckle_pitch*knuckle_count/2 - eps,
               knuckle_axis_y,
               -eps])
        cylinder(d = pin_dia, h = plate_length + 2*eps);
}
```

