// Leaf of a pin hinge
// Print orientation: flat plate on the bed, knuckles rising in +Z

// ---------- Parameters ----------
plate_len   = 60;    // plate length along X
plate_wid   = 20;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

knuckle_n     = 5;   // number of segments
knuckle_pitch = 12;  // segment length (plate_len / knuckle_n)
knuckle_d     = 8;   // knuckle cylinder diameter
knuckle_y     = 10;  // knuckle axis Y position (on +Y edge)
knuckle_z     = 4;   // knuckle axis height above bed

pin_d         = 2;   // pin hole diameter

eps           = 0.5; // cutter overshoot past faces
$fn           = 96;  // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (odd indices)
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0) {
                x = (i * knuckle_pitch - (knuckle_n - 1) * knuckle_pitch / 2);
                translate([x, knuckle_y, 0])
                    cylinder(d = knuckle_d, h = knuckle_z, $fn = $fn);
            }
        }
    }

    // Pin holes through every knuckle along the X axis
    for (i = [0 : knuckle_n - 1]) {
        if (i % 2 == 0) {
            x = (i * knuckle_pitch - (knuckle_n - 1) * knuckle_pitch / 2);
            translate([x, knuckle_y, 0])
                cylinder(d = pin_d, h = knuckle_z + 2 * eps, $fn = $fn);
        }
    }
}
