// Print orientation: flat on bed, z = 0 to plate_t

// ---------- Parameters ----------
outer_r   = 40;   // distance of outer points from centre
inner_r   = 20;   // distance of inner points from centre
point_n   = 6;    // number of points (evenly spaced)
plate_t   = 5;    // plate thickness
hole_d    = 8;    // central through-hole diameter
eps       = 0.5;  // cutter overshoot past faces

$fn = 96;

// ---------- Model ----------
difference() {
    // Star outline: outer points at 0°, 60°, ... ; inner points at 30°, 90°, ...
    linear_extrude(height = plate_t)
        polygon(points = [
            for (i = [0 : point_n - 1])
                rotate([0, 0, i * 360 / point_n])
                    [outer_r, 0];
            for (i = [0 : point_n - 1])
                rotate([0, 0, i * 360 / point_n + 180 / point_n])
                    [inner_r, 0];
        ]);

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
```

