    hull() {
        for (i = [0 : point_n - 1]) {
            a = i * 360 / point_n;
            // outer point on +X axis (a = 0)
            translate([outer_r * cos(a), outer_r * sin(a), 0])
                cube([1, 1, plate_t]);
            // inner point rotated by 180/point_n = 30 deg
            translate([inner_r * cos(a + 180 / point_n),
                       inner_r * sin(a + 180 / point_n), 0])
                cube([1, 1, plate_t]);
        }
    }

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
