pocket_depth   = 8;     // depth of the pocket from the top face (mm)
overcut        = 0.5;   // extra length so cutters pass through faces (mm)
$fn            = 64;    // curve resolution (for consistency)

// Derived values
pocket_floor_z = block_height - pocket_depth;          // z of the pocket bottom face
block_volume   = (block_bottom + block_top) / 2 * block_bottom * block_top * block_height;

// ---------------- Model ----------------
difference() {
    // Tapered square frustum: bottom face on the bed, top face at z = block_height
    // Sides slope inward while staying parallel to X and Y
    hull() {
        for (z = [0 : block_height / 2 : block_height]) {
            side_len = block_bottom - (block_bottom - block_top) * z / block_height;
            translate([0, 0, z])
                cube([side_len, side_len, 1]);   // 1 mm thick slice, no overlap
        }
    }

    // Square pocket cut into the top face, centred, open to the top
    translate([0, 0, pocket_floor_z])
        cube([pocket_size, pocket_size, pocket_depth + overcut]);
}
