// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness   = 3;     // specimen thickness (Z)
total_len   = 110;   // overall length along X
gauge_w     = 8;     // gauge section width (Y)
gauge_len   = 40;    // gauge section length (X)
grip_w      = 19;    // grip section width (Y)
grip_len    = 25;    // grip section length (X)
trans_len   = 10;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_gauge = gauge_len / 2;
half_grip  = grip_len / 2;
// centre of each region (grip, transition, gauge, transition, grip)
region_c = [
    -half_grip - trans_len,   // left grip
    -half_gauge - trans_len,  // left transition
    0,                        // gauge
    half_gauge + trans_len,   // right transition
    half_grip + trans_len     // right grip
];

// ---------- Model ----------
difference() {
    // main plate
    translate([-total_len / 2, -thickness / 2, 0])
        cube([total_len, thickness, 10]);

    // cut out grip and transition regions (from top, with overshoot)
    for (c = region_c)
        translate([c, -grip_w / 2 - eps, eps])
            cube([grip_len, grip_w + 2 * eps, thickness + 2 * eps]);

    // gauge section: V groove (saw-cut) along Y, extended in Z
    // so the cut passes through the full thickness
    translate([-half_gauge, -gauge_w / 2 - eps, -eps])
        rotate([90, 0, 0])
            linear_extrude(height = thickness + 2 * eps)
                polygon([
                    [-gauge_w / 2 - eps, 0],
                    [ gauge_w / 2 + eps, 0],
                    [ 0, -gauge_len / 2 - eps],
                    [ 0, gauge_len / 2 + eps]
                ]);
}
