w1    = grip_width;                                        // start width
w2    = gauge_width;                                       // end width

module dogbone() {
    hull() {
        for (s = [-1, 1]) {
            translate([s * grip_length - grip_length / 2, -w1 / 2, 0])
                cube([grip_length, w1, thickness]);   // grip sections
            translate([mid_x - transition_len, -w1 / 2, 0])
                cube([transition_len, w1, thickness]); // right transition
            translate([mid_x - gauge_length - transition_len, -w2 / 2, 0])
                cube([gauge_length, w2, thickness]);   // gauge section
            translate([mid_x + transition_len, -w1 / 2, 0])
                cube([transition_len, w1, thickness]); // left transition
        }
    }
}

dogbone();
