```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to specimen_t

$fn = 64;

// --- Dimensions (mm) ---
specimen_t   = 3;     // thickness (Z)
gauge_w      = 8;     // gauge section width (Y)
gauge_l      = 50;    // gauge section length (X)
grip_w       = 15;    // grip section width (Y)
grip_l       = 25;    // grip section length (X)
transition_l = 15;    // transition section length (X)

// Derived
total_l = 2 * grip_l + gauge_l + 2 * transition_l; // 130 mm

// Width at start of each region
function grip_w_start(x) = (x < 0) ? grip_w : grip_w;
function trans_w_start(x) = (x < 0) ? grip_w : grip_w;
function trans_w_end(x)   = (x > 0) ? gauge_w : grip_w;

module profile() {
    union() {
        // Left grip
        translate([-total_l / 2, -grip_w / 2, 0])
            cube([grip_l, grip_w, specimen_t]);

        // Right grip
        translate([total_l / 2 - grip_l, -grip_w / 2, 0])
            cube([grip_l, grip_w, specimen_t]);

        // Gauge section
        translate([-total_l / 2 + grip_l - transition_l, -gauge_w / 2, 0])
            cube([gauge_l, gauge_w, specimen_t]);

        // Transitions (linear width change)
        for (s = [-1, 1]) {
            x0 = -total_l / 2 + grip_l;
            // Hull between grip end and gauge end, then slice to length
            hull() {
                translate([x0, -grip_w / 2, 0])
                    cube([transition_l, grip_w, specimen_t]);
                translate([x0 + s * transition_l, -gauge_w / 2, 0])
                    cube([transition_l, gauge_w, specimen_t]);
            }
        }
    }
}

difference() {
    linear_extrude(height = specimen_t)
        profile();

    // Small cut to avoid coplanar faces
    translate([-total_l / 2 - 1, -grip_w / 2, 0])
        cube([total_l + 2, grip_w + 2, specimen_t + 0.5]);
}
