// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness   = 3;     // specimen thickness (Z)
total_len   = 130;   // overall length along X
gauge_w     = 6;     // gauge section width (Y)
gauge_len   = 50;    // gauge section length (X)
grip_w      = 15;    // grip section width (Y)
grip_len    = 30;    // grip section length (X)
trans_len   = 10;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_gauge = gauge_len / 2;
half_grip  = grip_len / 2;
// transition runs from end of grip (x = half_grip) to start of gauge (x = half_gauge)

// ---------- Width profile (seen from above) ----------
function width(x) =
    if (x < -half_grip)
        grip_w
    else if (x <= -half_gauge)
        // linear drop from 15 to 6 over the left transition
        grip_w + (6 - grip_w) * (x + half_grip) / trans_len
    else if (x <= half_gauge)
        gauge_w
    else if (x <= half_grip)
        // linear rise from 6 to 15 over the right transition
        gauge_w + (grip_w - gauge_w) * (x - half_gauge) / trans_len
    else
        grip_w;

// ---------- Model ----------
difference() {
    // main plate
    hull() {
        for (sx = [-1, 1])
            translate([sx * half_grip, -width(half_grip) / 2, 0])
                cube([grip_len, width(half_grip), thickness]);
    }
    // central relief to keep the gauge section at the stated 50 mm length
    translate([-half_gauge - eps, -width(-half_gauge - eps) / 2, -eps])
        cube([gauge_len + 2 * eps, width(-half_gauge - eps), thickness + 2 * eps]);
}
