$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // width of central gauge section (Y)
gauge_length   = 30;    // length of gauge section along X
grip_width     = 20;    // width of grip sections (Y)
grip_length    = 35;    // length of each grip section along X
transition_len  = 15;    // length of each grip-to-gauge transition
cut_extra      = 0.5;   // overshoot for clean boolean cuts

// Derived
grip_x0        = -total_length/2 + grip_length;  // grip start X
gauge_x0       = grip_x0 + grip_length;          // gauge start X
transition_x0  = gauge_x0 - transition_len;      // transition start X

// Width profile seen from above (y = 0 at centreline)
function width(x) =
    if (x < transition_x0)
        grip_width/2 + (gauge_width - grip_width)/2 *
            (x - (grip_x0 - transition_len)) / transition_len;
    else if (x <= gauge_x0 + transition_len)
        gauge_width/2 + (grip_width - gauge_width)/2 *
            (x - gauge_x0 - transition_len) / transition_len;
    else
        grip_width/2 + (gauge_width - grip_width)/2 *
            (x - (gauge_x0 + transition_len)) / transition_len;

difference() {
    // Main body
    hull() {
        for (sx = [-1, 1])
            translate([sx * grip_x0 - grip_length, -width(grip_x0 - grip_length), 0])
                cube([grip_length, grip_width, thickness]);
        for (sx = [-1, 1])
            translate([sx * (gauge_x0 + transition_len), -width(gauge_x0 + transition_len), 0])
                cube([gauge_x0 + transition_len - (gauge_x0 - transition_len),
                       grip_width, thickness]);
    }

    // Central gauge cut (extends past faces)
    translate([-gauge_length/2, -gauge_width/2, -cut_extra])
        cube([gauge_length, gauge_width, thickness + 2*cut_extra]);
}
