```openscad
// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 to plate_t

// ---- Parameters ----
outer_r   = 30;   // distance of outer points from centre
inner_r   = 15;   // distance of inner points from centre
points    = 5;    // number of points (and inner points)
plate_t   = 3;    // plate thickness
hole_d    = 8;    // central through-hole diameter
eps       = 0.5;  // cutter overshoot past faces

$fn = 96;

// ---- Model ----
difference() {
    // Star outline: outer points at 0, 72, ... deg; inner points at 36, 108, ...
    hull() {
        for (i = [0 : points - 1]) {
            a = i * 360 / points;
            // outer point
            translate([outer_r * cos(a), outer_r * sin(a), 0])
                cylinder(h = plate_t, r = outer_r, $fn = 96);
            // inner point
            translate([inner_r * cos(a + 180 / points),
                       inner_r * sin(a + 180 / points), 0])
                cylinder(h = plate_t, r = inner_r, $fn = 96);
        }
    }

    // Central through hole
    translate([0, 0, -eps])
        cylinder(h = plate_t + 2 * eps, d = hole_d, $fn = 96);
}
```

