// Tapered riser block for a beaker, with a square pocket in the top face
// Print orientation: base on the bed (z = 0), pocket facing up

// ---------- Dimensions (mm) ----------
base_size   = 100;   // bottom square side length (z = 0)
top_size    = 80;    // top square side length (z = 30)
height      = 30;    // overall height of the frustum
pocket_w    = 72;    // pocket side length
pocket_d    = 5;     // pocket depth from the top face
eps         = 0.5;   // overshoot for clean boolean cuts

$fn = 64;

// ---------- Model ----------
difference() {
    // Square frustum: base at z = 0, top face at z = height
    linear_extrude(height = height)
        polygon([
            [-base_size/2, -base_size/2],
            [ base_size/2, -base_size/2],
            [ base_size/2,  base_size/2],
            [-base_size/2,  base_size/2]
        ]);

    // Square pocket, centred, open at the top
    translate([0, 0, height - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}
