    translate([-gauge_x0, -gauge_w/2, 0])
        cube([gauge_l, gauge_w, specimen_t]);

    // Transition regions
    for (s = [trans_x0, gauge_x1 + transition_l])
        translate([s, -trans_w(s, s + transition_l)/2, 0])
            cube([transition_l, trans_w(s, s + transition_l), specimen_t]);
