$fn = 64;

// --- Dimensions (mm) ---
specimen_t   = 3;     // thickness (Z)
gauge_w      = 6;     // gauge section width (Y)
gauge_l      = 30;    // gauge section length (X)
grip_w       = 15;    // grip section width (Y)
grip_l       = 30;    // grip section length (X)
transition_l = 15;    // transition section length (X)
total_l      = 120;   // overall length (X)

