half_grip   = grip_w / 2;
half_gauge  = gauge_w / 2;
eps         = 0.5;    // cutter overshoot

// Check: 2*grip_l + gauge_l + 2*transition_l = 120
assert(abs(2*grip_l + gauge_l + 2*transition_l - total_l) < 0.001, "Length mismatch");

module dog_bone() {
    difference() {
        // Outer profile (seen from above), extruded through thickness
        linear_extrude(height = specimen_t) {
            hull() {
                // Left grip
                translate([-total_l/2, -half_grip, 0])
                    cube([grip_l, grip_w, specimen_t + 2*eps]);
                // Right grip
                translate([total_l/2 - grip_l, -half_grip, 0])
                    cube([grip_l, grip_w, specimen_t + 2*eps]);
                // Gauge section
                translate([-total_l/2 + grip_l + transition_l, -half_gauge, 0])
                    cube([gauge_l, gauge_w, specimen_t + 2*eps]);
            }
        }
        // Optional: clean up any coincident faces in the transition
        translate([-total_l/2 + grip_l + 0.01, -half_grip, 0])
            cube([transition_l + 0.01, grip_w, eps]);
    }
}

dog_bone();
