difference() {
    // T profile (flange + neck)
    union() {
        // Bottom flange: z = 0 to 2, Y = -5 to 5, X = -5 to 5
        translate([center_x, -flange_width / 2, 0])
            cube([x_length, flange_width, flange_thick]);

        // Neck: z = 2 to 5, Y = -3 to 3, X = -5 to 5
        translate([center_x, -neck_width / 2, flange_thick])
            cube([x_length, neck_width, neck_top_z - flange_thick]);
    }

    // Vertical screw hole through the centre, past both faces
    translate([0, 0, -screw_overcut])
        cylinder(d = screw_d, h = neck_top_z + 2 * screw_overcut);
