// Cable bridge - rectangular block with 3 semicircular tunnels along Y at floor level
// Print orientation: block stands on the bed (z = 0), tunnels open downward.

// ---------------- Parameters ----------------
block_len    = 80;    // block length along X (mm)
block_wid    = 30;    // block width along Y (mm)
block_ht     = 15;    // block height along Z (mm)

tunnel_d     = 8;     // tunnel diameter (mm); radius = d/2 = 4 mm
tunnel_count = 3;     // number of tunnels
tunnel_pitch = 16;    // centre-to-centre spacing of tunnels along X (mm)
tunnel_r     = tunnel_d / 2;  // tunnel radius (mm)

eps          = 0.5;   // overcut so cutters pass beyond the faces they cut (mm)

$fn = 96;             // circle resolution

// ---------------- Derived ----------------
// X position of the first tunnel so the set is centred on the origin
tunnel_x0 = -(tunnel_count - 1) * tunnel_pitch / 2;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular tunnels: cylinder axes lie along Y at z = 0,
    // running from x = -inf to x = +inf through the block.
    for (i = [0 : tunnel_count - 1])
        translate([tunnel_x0 + i * tunnel_pitch, 0, 0])
            translate([0, 0, -eps])
                cylinder(h = block_ht + 2 * eps, r = tunnel_r);
}
