// Leaf of a pin hinge
// Print orientation: flat plate on the bed, knuckles pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 45;    // plate length along X (mm)
plate_wid   = 25;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness along Z (mm)

knuckle_d   = 8;     // knuckle cylinder diameter (mm)
knuckle_y   = 12.5;  // knuckle axis Y position (mm)
knuckle_h   = 4;     // knuckle height above plate top (mm)

pin_d       = 2;     // pin hole diameter (mm)
pin_overlap = 0.5;   // extra pin length into knuckles for a clean cut (mm)

seg_count   = 3;     // number of equal segments along the plate
seg_len     = plate_len / seg_count; // 15 mm per segment

eps         = 0.5;   // general cutter overshoot past faces (mm)

$fn = 96;            // smoothness of curved surfaces

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on the +Y edge: 1st and 3rd segments only
    for (i = [0, seg_count - 1]) {
        x_c = -seg_len / 2 + i * seg_len + seg_len / 2;
        translate([x_c, knuckle_y, plate_thk])
            cylinder(d = knuckle_d, h = knuckle_h);
    }

    // Pin hole running along X through every knuckle
    translate([-seg_len / 2 - pin_overlap, knuckle_y, 0])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = seg_len + 2 * pin_overlap);
}
```

