```openscad
// Leaf of a pin hinge
// Print orientation: flat plate on the bed, knuckles rising in +Z

// ---------- Parameters ----------
plate_length   = 60;    // plate length along X (mm)
plate_width    = 25;    // plate width along Y (mm)
plate_thick    = 2.5;   // plate thickness along Z (mm)

knuckle_count  = 5;     // number of segments along the edge
knuckle_pitch  = 12;    // length of each segment (mm)
knuckle_dia    = 6;     // knuckle cylinder diameter (mm)
knuckle_axis_y = 12.5;  // knuckle axis Y position (mm)
knuckle_z      = 3;     // knuckle axis height above bed (mm)

pin_dia        = 2;     // pin hole diameter (mm)

eps            = 0.5;   // cutter overshoot past faces (mm)
$fn            = 96;    // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_length/2, -plate_width/2, 0])
            cube([plate_length, plate_width, plate_thick]);

        // Knuckles on the +Y edge: 1st, 3rd, 5th segments
        for (i = [0 : knuckle_count - 1]) {
            if (i % 2 == 0) {
                x = (i - (knuckle_count - 1)/2) * knuckle_pitch;
                translate([x, knuckle_axis_y, 0])
                    cylinder(d = knuckle_dia, h = plate_thick + eps);
            }
        }
    }

    // Pin hole along the knuckle axis, through every knuckle
    translate([-(knuckle_count - 1)/2 * knuckle_pitch,
               knuckle_axis_y,
               -eps])
        cylinder(d = pin_dia, h = plate_thick + 2*eps);
}
