        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (odd indices)
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0) {
                x = -knuckle_p * knuckle_n / 2 + i * knuckle_p;
                translate([x, knuckle_y, knuckle_z])
                    cylinder(d = knuckle_d, h = 10);
            }
        }
    }

    // Pin holes through every knuckle along the X axis
    for (i = [0 : knuckle_n - 1]) {
        if (i % 2 == 0) {
            x = -knuckle_p * knuckle_n / 2 + i * knuckle_p;
            translate([x, knuckle_y, knuckle_z])
                rotate([0, 90, 0])
                    cylinder(d = pin_d, h = 10 + 2 * eps);
        }
    }
}
