        translate([eccentricity, 0, 0])
            cylinder(d = cam_d, h = cam_t);

        // Hub around shaft axis
        translate([0, 0, cam_t])
            cylinder(d = hub_d, h = hub_h);
    }

    // Shaft hole through hub and disc
        translate([0, 0, -eps])
            cylinder(d = shaft_d, h = cam_t + 2 * eps);
}
