            for (i = [0 : n_points - 1])
                each [
                    [outer_r * cos(36 * i), outer_r * sin(36 * i)],
                    [inner_r * cos(36 * i + 18), inner_r * sin(36 * i + 18)]
                ]
        ]);

    // Central hole, extends past top and bottom faces
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}
