// Print orientation: posts stand on the bed (z = 0), bar on top.

// ---------------- Parameters ----------------
post_d      = 12;    // post diameter (X and Y)
post_h      = 30;    // post height (z = 0 to 30)
post_x      = 48;    // post centre offset from origin (+X and -X)
bar_len     = 108;   // bar length along X
bar_w       = 12;    // bar width along Y
bar_t       = 6;     // bar thickness (z = 30 to 36)
screw_d     = 3.4;   // screw hole diameter
screw_depth = 10;    // screw hole depth from bottom face
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------------- Model ----------------
union() {
    // Two round posts
    for (sx = [-1, 1])
        translate([sx * post_x, 0, 0])
            cylinder(d = post_d, h = post_h);

    // Straight bar on top of the posts
    translate([-bar_len / 2, -bar_w / 2, post_h])
        cube([bar_len, bar_w, bar_t]);

    // Screw holes in each post, from bottom face upward
    for (sx = [-1, 1])
        translate([sx * post_x, 0, -eps])
            cylinder(d = screw_d, h = post_h + 2 * eps);
}
