// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness   = 4;     // specimen thickness (Z)
total_len   = 140;   // overall length along X
gauge_w     = 6;     // gauge section width (Y)
gauge_len   = 50;    // gauge section length (X)
grip_w      = 19;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
trans_len   = 10;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_gauge = gauge_len / 2;
half_grip  = grip_len / 2;
// centre of each grip relative to the gauge centre
grip_x0 = -(half_gauge + trans_len - half_grip);

// ---------- Model ----------
difference() {
    // Main body
    hull() {
        for (sx = [-1, 1])
            translate([sx * grip_x0, -grip_w / 2, 0])
                cube([grip_len, grip_w, thickness]);
        translate([-half_gauge, -gauge_w / 2, 0])
            cube([gauge_len, gauge_w, thickness]);
    }

    // Optional through-thickness core, leaving a skin on each face
    for (sx = [-1, 1])
        translate([sx * (half_gauge + trans_len / 2), 0, -eps])
            cube([gauge_len + 1, gauge_w + 4, thickness + 2 * eps]);
}
