```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // specimen thickness (Z)
total_length   = 140;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 10;    // length of each grip-to-gauge transition (X)

// ---- Derived ----
half_gauge = gauge_length / 2;
// grip outer edges at x = +/-60, gauge centre at x = 0,
// so the two transition regions are disjoint
overlap     = grip_length - half_gauge;

module width(x) {
    // linear width profile: grip (19) -> gauge (6) -> grip (19)
    w = grip_width + (6 - grip_width) * (abs(x) - overlap) / transition_len;
    // clamp the centre of each grip to the full grip width
    w = min(w, grip_width + (abs(x) < transition_len ? 1 : 0) * (grip_width - 6));
    w = max(w, 6);
    return w;
}

difference() {
    // single solid plate, centred in X/Y, resting on z = 0
    translate([-total_length / 2, -thickness / 2, 0])
        cube([total_length, thickness,
              for (sx = [-1, 1])
                  for (y = [0 : 0.01 : thickness])
                      union() {
                          translate([sx * half_gauge - 50, y, 0])
                              cube([gauge_length, width(y), thickness]);
                          translate([sx * (half_gauge + transition_len + 1), y, 0])
                              cube([grip_length, width(y), thickness]);
                      }
        ]);
}
