// ---------- Derived ----------
half_gauge = gauge_len / 2;
half_grip  = grip_len / 2;
// centre of each region (grip -> trans -> gauge -> trans -> grip)
region_c = [ -half_grip, -half_gauge, 0, half_gauge, half_grip ];

// ---------- Model ----------
difference() {
    // outer shape
    hull() {
        for (i = [0 : 4])
            translate([region_c[i], -grip_w / 2, 0])
                cube([grip_len, grip_w, thickness]);
    }

    // central groove along X, above the midplane
    translate([0, 0, thickness * 0.25])
        linear_extrude(height = gauge_len + 2 * trans_len + 1)
            polygon([
                [-trans_len, gauge_w / 2],
                [ trans_len, gauge_w / 2],
                [ trans_len, -gauge_w / 2],
                [-trans_len, -gauge_w / 2]
            ]);
}
