```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to specimen_t

$fn = 64;

// --- Dimensions (mm) ---
specimen_t   = 4;     // thickness (Z)
gauge_w      = 6;     // gauge section width (Y)
gauge_l      = 50;    // gauge section length (X)
grip_w       = 15;    // grip section width (Y)
grip_l       = 35;    // grip section length (X)
transition_l = 15;    // transition section length (X)

// Derived
total_l = 2 * grip_l + gauge_l + 2 * transition_l; // 150 mm

difference() {
    // Body
    union() {
        // Grip sections
        for (s = [-1, 1])
            translate([s > 0 ? grip_l - transition_l : -grip_l, -grip_w / 2, 0])
                cube([grip_l + transition_l, grip_w, specimen_t]);
        // Gauge section
        translate([-gauge_l / 2, -gauge_w / 2, 0])
            cube([gauge_l, gauge_w, specimen_t]);
        // Transitions (linear width change)
        for (s = [-1, 1])
            translate([s > 0 ? grip_l - transition_l : -grip_l, 0, 0])
                linear_extrude(height = specimen_t)
                    polygon([
                        [0, -grip_w / 2],
                        [transition_l, -grip_w / 2],
                        [transition_l, grip_w / 2],
                        [0, grip_w / 2]
                    ]);
    }

    // Optional through-hole in gauge section for alignment
    translate([-gauge_l / 2, 0, -1])
        cylinder(d = 3, h = gauge_l + 2);
}
