// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness   = 4;     // specimen thickness (Z)
total_len   = 120;   // overall length along X
gauge_w     = 8;     // gauge section width (Y)
gauge_len   = 30;    // gauge section length (X)
grip_w      = 19;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
trans_len   = 10;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_grip   = grip_w / 2;
half_gauge  = gauge_w / 2;
reach       = grip_len + trans_len;   // distance from origin to grip end

// ---------- Model ----------
difference() {
    // Solid body
    hull() {
        for (s = [-1, 1])
            translate([s * reach, 0, 0])
                rotate([0, 0, s * 90])
                    linear_extrude(thickness)
                        polygon([[-half_grip, -half_grip],
                                 [ half_grip, -half_grip],
                                 [ half_grip,  half_grip],
                                 [−half_grip,  half_grip]]);
    }

    // Central gauge section (overcut along Z)
    translate([-gauge_len / 2, -half_gauge, -eps])
        cube([gauge_len, gauge_w, thickness + 2 * eps]);

    // Grip sections (overcut along X)
    for (s = [-1, 1])
        translate([s * (total_len / 2 - grip_len), -half_grip, -eps])
            cube([grip_len, grip_w, thickness + 2 * eps]);
}
