// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // plate thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 10;    // length of each grip-gauge transition (X)

// ---- Derived ----
grip_x0 = -(total_length / 2) + grip_length;   // grip start X
gauge_x0 = grip_x0 + grip_length;              // gauge start X
trans_x0 = gauge_x0 - transition_len;          // transition start X
trans_x1 = trans_x0 + transition_len;          // transition end X

// ---- Width profile (seen from above) ----
function width(x) =
    if (x < trans_x0) grip_width
    else if (x <= gauge_x0) linear_map(x, trans_x0, gauge_x0, grip_width, gauge_width)
    else if (x <= trans_x1) linear_map(x, gauge_x0, trans_x1, gauge_width, grip_width)
    else grip_width;

difference() {
    // Main plate
    translate([-total_length / 2, -thickness / 2, 0])
        linear_extrude(thickness)
            polygon([for (sx = [-1, 1]) for (sy = [-1, 1])
                [sx * (total_length / 2 - grip_length + 1),
                 sy * thickness / 2 + thickness / 3]]);

    // Central gauge section (overlaps slightly into transitions for clean cut)
    translate([gauge_x0 - 1, -gauge_width / 2, 0])
        cube([gauge_length + 2, gauge_width, thickness]);
}
