half_gauge = gauge_length / 2;
half_grip  = grip_length / 2;
// width at the start of each transition (at the grip end)
transition_w0 = grip_width + (gauge_width - grip_width) * (transition_len / (gauge_length + 2 * transition_len));

difference() {
    // Single solid plate
    translate([-total_length / 2, -thickness / 2, 0])
        linear_extrude(thickness)
            polygon([
                // Left grip
                for (x = [-total_length / 2 - half_grip : 1 : -total_length / 2 + half_grip])
                    [x, -grip_width / 2],
                // Left transition (outer -> inner)
                for (t = [0 : transition_len / 2 : gauge_length / 2])
                    [-(half_grip + t), gauge_width / 2 - (gauge_width - grip_width) * t / (gauge_length + 2 * transition_len) / 2],
                // Gauge section
                for (x = [-half_gauge : 1 : half_gauge])
                    [x, gauge_width / 2],
                // Right transition (inner -> outer)
                for (t = [gauge_length / 2 : -transition_len / 2 : -gauge_length / 2])
                    [half_grip + t, gauge_width / 2 - (gauge_width - grip_width) * t / (gauge_length + 2 * transition_len) / 2],
                // Right grip
                for (x = [total_length / 2 - half_grip : 1 : total_length / 2 + half_grip])
                    [x, -grip_width / 2]
            ]);
}
