// Stiffened cover panel: flat plate with 3 transverse ribs
// Print orientation: plate flat on bed, ribs pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 120;   // plate length along X (mm)
plate_wid   = 80;    // plate width along Y (mm)
plate_thk   = 2;     // plate thickness (mm), z = 0..2

rib_thk     = 3;     // rib thickness along X (mm)
rib_h       = 4;     // rib height above plate (mm), z = 2..6
rib_count   = 3;     // number of ribs
rib_pitch   = 30;    // centre-to-centre spacing of ribs (mm)
rib_offset  = 30;    // distance of outer rib centres from plate ends (mm)

eps         = 0.5;   // overlap for clean boolean unions (mm)
$fn         = 64;    // curve resolution (no curves here; kept per convention)

// ---------------- Derived ----------------
// Ribs divide the plate into 4 equal parts: check spacing
first_x = -plate_len/2 + rib_offset;   // centre of left rib
last_x  = plate_len/2 - rib_offset;    // centre of right rib
// middle rib is centred on the origin (symmetry)
rib_x_pos = [first_x, 0, last_x];

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running full width along Y
    for (x = rib_x_pos)
        translate([x - rib_thk/2, -plate_wid/2, plate_thk])
            cube([rib_thk, plate_wid, rib_h]);
}
```

