rib_h       = 6;     // rib height above plate (mm), z = 3..9
rib_count   = 3;     // number of ribs
rib_pitch   = 20;    // centre-to-centre spacing of ribs (mm)
rib_offset  = 20;    // distance of outer ribs from plate ends (mm)

eps         = 0.5;   // overlap for clean booleans (mm)
$fn         = 64;    // curve resolution (no curves here, set per rules)

// ---------------- Derived ----------------
plate_h = plate_thk + rib_h;   // overall height (9 mm)

// Check: 4 equal parts -> pitch = len / 4 = 20 mm, matches given
assert(abs(rib_pitch - plate_len / 4) < 0.001, "Rib pitch must give 4 equal parts");

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred on origin along X
    for (i = [0 : rib_count - 1]) {
        x_c = (i - (rib_count - 1)/2) * rib_pitch;
        translate([x_c - rib_thk/2, -plate_wid/2, plate_thk])
            cube([rib_thk, plate_wid, rib_h]);
    }
}
