```openscad
// Powder measuring scoop - hollow spherical bowl with a flat handle along +X
// Print orientation: bowl bottom on the bed (z = 0), handle on top, opening upward.

$fn = 96;

// ---- Bowl ----
outer_radius   = 15;    // mm, outer radius of the sphere
wall_thickness = 2;     // mm, wall thickness of the bowl
rim_z          = 15;    // mm, z of the rim (sphere centre height)
bottom_z       = 0;     // mm, z where the bowl touches the bed

// ---- Handle ----
handle_length = 82;     // mm, handle runs from x = 13 to x = 95
handle_width  = 8;      // mm, handle width along Y
handle_thick  = 3;      // mm, handle thickness (Z)
handle_x0     = 13;     // mm, start of handle
handle_x1     = 95;     // mm, end of handle

// ---- Misc ----
eps           = 0.5;    // mm, cutter overshoot past faces
overlap       = 0.01;   // mm, small overlap so handle fuses into the rim

difference() {
    union() {
        // Lower half of a hollow sphere: outer radius R, inner radius R - t,
        // centred at (0, 0, rim_z), kept from z = 0 up to the rim.
        hull() {
            translate([0, 0, bottom_z])
                cylinder(h = rim_z, r = outer_radius);
            translate([0, 0, rim_z - wall_thickness])
                cylinder(h = wall_thickness + eps, r = outer_radius);
        }

        // Flat handle along +X, centred on y = 0, top face flush with the rim
        translate([handle_x0, -handle_width / 2, rim_z - handle_thick])
            cube([handle_length, handle_width, handle_thick]);
    }

    // Remove the upper half of the outer sphere (above the rim),
    // extended past the rim by eps so no faces are coplanar.
    translate([0, 0, rim_z + eps])
        cylinder(h = outer_radius + 2 * eps, r = outer_radius);
}
