// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
sphere_r      = 15;    // outer radius of spherical bowl
wall          = 1.5;   // bowl wall thickness
handle_w      = 8;     // handle width (Y)
handle_t      = 4;     // handle thickness (Z)
handle_x0     = 13.5;  // handle start (X)
handle_x1     = 75;    // handle end (X)
cut_extra     = 0.5;   // extra length on cutting shapes to avoid coplanar faces

$fn = 96;

// ---------------- Derived ----------------
rim_z   = sphere_r;               // rim is at the equator (z = 15)
// handle top face flush with rim: handle spans z = 11 to z = 15
handle_y0 = -handle_w / 2;        // -4 to +4 in Y

// ---------------- Model ----------------
union() {
    // Lower half of hollow sphere: z = 0 to z = 15
    difference() {
        translate([0, 0, sphere_r])
            sphere(r = sphere_r);
        translate([0, 0, sphere_r - wall])
            sphere(r = sphere_r - wall);
    }

    // Flat handle along +X
    translate([handle_x0, handle_y0, rim_z - handle_t])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}
