tunnel_pitch = 20;    // centre-to-centre spacing of tunnel axes along X (mm)
tunnel_h     = 0;     // tunnel axis height (mm) - floor level

eps          = 0.5;   // overshoot so cutters pass beyond the faces they cut (mm)
$fn          = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_h]);

    // Semicircular tunnels: cylinders along Y, axes at floor level
    for (i = [0 : 1]) {
        x = i * tunnel_pitch - tunnel_pitch/2;   // axis X position (-10, +10)
        translate([x, 0, tunnel_h])
            rotate([90, 0, 0])
                cylinder(d = tunnel_d, h = block_wid + 2*eps, center = true);
    }
}
