// Torus: cross-section circle sweeps around Z axis
module ring_weight() {
    difference() {
        linear_extrude(height = cross_section_r + cut_extra)
            rotate([0, 90, 0])
                circle(r = ring_radius, $fn = 128);
        // remove the lower half so the part rests on z = 0
        translate([0, 0, bed_z])
            cylinder(r = cross_section_r + cut_extra,
                     h = middle_z + cut_extra, $fn = 96);
    }
}

ring_weight();
