// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 60;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 3;     // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 8;     // knuckle diameter
knuckle_n   = 3;     // number of knuckles
knuckle_pitch = plate_len / knuckle_n; // 20 mm spacing
knuckle_y   = plate_wid / 2;          // 12.5 mm (on +Y edge)
knuckle_z   = 4;                      // axis height above bed

// ---- Pin hole ----
pin_d = 3;            // pin hole diameter

// ---- Misc ----
eps = 0.5;            // cutter overshoot past faces

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders on 1st and 3rd segments
        for (i = [0, knuckle_n - 1]) {
            x = -knuckle_pitch * (knuckle_n - 1) / 2 + i * knuckle_pitch;
            translate([x, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 2*eps);
        }
    }

    // Pin hole along the knuckle axis through every knuckle
    translate([-knuckle_pitch * (knuckle_n - 1) / 2, knuckle_y, knuckle_z])
        translate([0, 0, -eps])
            cylinder(d = pin_d, h = plate_thk + 2*eps);
}
