// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness   = 4;     // specimen thickness (Z)
total_len   = 140;   // overall length along X
gauge_w     = 6;     // gauge section width (Y)
gauge_len   = 40;    // gauge section length (X)
grip_w      = 15;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
trans_len   = 15;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_grip   = grip_w / 2;
half_gauge  = gauge_w / 2;
reach       = grip_len + trans_len;   // distance from origin to grip end
area        = gauge_w * thickness;    // gauge cross-section area

// ---------- Model ----------
difference() {
    // Main body
    hull() {
        // End grip blocks
        translate([-total_len / 2, -half_grip, 0])
            cube([grip_len, grip_w, thickness]);
        translate([total_len / 2 - grip_len, -half_grip, 0])
            cube([grip_len, grip_w, thickness]);

        // Central gauge block
        translate([-gauge_len / 2, -half_gauge, 0])
            cube([gauge_len, gauge_w, thickness]);
    }

    // Grip-end transition grooves (width reduces from grip_w to gauge_w)
    for (s = [-1, 1])
        translate([s * (gauge_len / 2 + eps), -reach, -eps])
            rotate([90, 0, 0])
                linear_extrude(thickness)
                    polygon([
                        [0, -half_grip],
                        [trans_len, -half_grip],
                        [trans_len, half_grip],
                        [0, half_grip]
                    ]);

    // Optional through-hole in gauge section
    translate([0, 0, -eps])
        cylinder(d = 4, h = thickness + 2 * eps, $fn = 64);
}
