    // Rubber pad recess in bottom face
    translate([0, 0, -eps])
        cylinder(d = recess_d, h = recess_depth + eps);

    // Through screw hole
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = foot_h + 2 * eps);
}
