wall_thickness = 1.5;   // bowl wall thickness (mm)
handle_width  = 10;    // handle width along Y (mm)
handle_thick  = 4;     // handle thickness along Z (mm)
handle_x0     = 13.5;  // handle start position along X (mm)
handle_x1     = 115;   // handle end position along X (mm)
cut_extra     = 0.5;   // extra length on cutting shapes to avoid coplanar faces (mm)

$fn = 96;              // curve resolution

// Derived values
rim_z      = outer_radius;               // rim height (lower half: z = 0..15)
inner_r    = outer_radius - wall_thickness;
handle_h0  = rim_z - handle_thick;       // handle bottom face height (z = 11)
handle_h1  = rim_z;                      // handle top face height (z = 15)

// ---------------- Model ----------------
union() {
    // Hollow spherical bowl (lower half only)
    translate([0, 0, rim_z])
        difference() {
            sphere(r = outer_radius);
            translate([0, 0, cut_extra])
                sphere(r = inner_r + 2 * cut_extra);
        }
    // Keep only the part below z = rim_z + cut_extra to avoid the upper hemisphere
    difference() {
