        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders
        for (i = [0:knuckle_n-1])
            if (knuckle_ks[i])
                translate([knuckle_x0 + i*pitch, knuckle_y, knuckle_z])
                    cylinder(d = knuckle_d, h = 10, $fn = 64);
