knuckle_pitch = plate_len / knuckle_count; // 8 mm segment length
knuckle_y     = plate_wid / 2;             // 12.5 mm
knuckle_z     = 4;                         // 1.5 mm overlap into plate

// ---- Pin ----
pin_d = 2;           // pin hole diameter

// ---- Model ----
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on 1st, 3rd, 5th segments, axis along X
    for (i = [0 : knuckle_count - 1]) {
        if (i % 2 == 0) {
            translate([(i - 2) * knuckle_pitch, knuckle_y, knuckle_z])
                cylinder(r = knuckle_r, h = plate_thk + 2 * knuckle_r);
        }
    }

    // Pin holes through every knuckle
    for (i = [0 : knuckle_count - 1]) {
        if (i % 2 == 0) {
            translate([(i - 2) * knuckle_pitch, knuckle_y, knuckle_z])
                translate([0, 0, -1])
                    cylinder(d = pin_d, h = plate_thk + 2 * knuckle_r + 2);
        }
    }
}
