points    = 8;     // number of spikes (outer/inner pairs)
thickness = 3;     // plate thickness
hole      = 6;     // central through-hole diameter
eps       = 0.5;   // cutter overshoot past faces

$fn = 96;

difference() {
    // Star outline: alternate between outer and inner points,
    // starting with an outer point on +X (angle 0)
    linear_extrude(thickness)
        polygon([for (i = [0 : points - 1])
            let (a = i * 360 / points - 90)
                [outer_r * cos(a), outer_r * sin(a),
                 inner_r * cos(a + 180 / points), inner_r * sin(a + 180 / points)]]);

    // Central hole
    translate([0, 0, -eps])
        cylinder(d = hole, h = thickness + 2 * eps);
}
