    // Star outline: outer points at 0,45,... deg, inner points shifted by 22.5 deg
    hull() {
        for (i = [0 : points - 1]) {
            rotate([0, 0, i * 360 / points])
                translate([0, 0, 0])
                    cylinder(h = thickness, r = outer_r);   // outer point
            rotate([0, 0, i * 360 / points + 360 / points / 2])
                translate([0, 0, 0])
                    cylinder(h = thickness, r = inner_r);   // inner point
        }
    }

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(h = thickness + 2 * eps, d = hole_d);
}
