// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 10;    // length of each grip-gauge transition (X)

// ---- Derived ----
half_gauge = gauge_length / 2;
half_grip  = grip_length / 2;
// grip end x = -total_length/2 + half_grip ; gauge end x = -half_gauge
// check: -60 + 35 = -25 ; -15 = -15

// ---- Model ----
difference() {
    // Outer shape: grip -> transition -> gauge -> transition -> grip
    union() {
        // Grip sections
        for (s = [-1, 1])
            translate([s * (total_length / 2 - half_grip), -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
        // Gauge section
        translate([-half_gauge, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            x0 = s * (total_length / 2 - half_grip);   // grip end
            x1 = s * half_gauge;                        // gauge end
            w0 = grip_width;
            w1 = gauge_width;
            // for loop over transition_len segments
            for (i = [0 : transition_len - 1]) {
                t = (i + 0.5) / transition_len;
                translate([s * (-total_length / 2 + x0 + (i + 1) * transition_len / transition_len),
                           -w0 / 2 + (w1 - w0) * t / 2, 0])
                    cube([transition_len, w0 + (w1 - w0) * t / 2, thickness]);
            }
        }
    }
    // Cut a little past faces to avoid coplanar surfaces
    translate([-total_length / 2 - 1, -gauge_width / 2 - 1, -1])
        cube([total_length + 2, gauge_width + 2, thickness + 2]);
}
