```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to specimen_t

$fn = 64;

// --- Dimensions (mm) ---
specimen_t   = 3;     // thickness (Z)
gauge_w      = 6;     // gauge section width (Y)
gauge_l      = 50;    // gauge section length (X)
grip_w       = 19;    // grip section width (Y)
grip_l       = 25;    // grip section length (X)
transition_l = 15;    // transition section length (X)

// Derived
total_l = 2 * grip_l + gauge_l + 2 * transition_l; // 130 mm

// Width at start of each transition: grip_w -> gauge_w
// Slope: (gauge_w - grip_w) / transition_l
slope = (gauge_w - grip_w) / transition_l;

module dog_bone() {
    union() {
        // Left grip
        translate([-total_l / 2 + grip_l, -grip_w / 2, 0])
            cube([grip_l, grip_w, specimen_t]);

        // Right grip
        translate([total_l / 2 - grip_l, -grip_w / 2, 0])
            cube([grip_l, grip_w, specimen_t]);

        // Gauge section
        translate([-gauge_l / 2, -gauge_w / 2, 0])
            cube([gauge_l, gauge_w, specimen_t]);

        // Transitions (mirror across origin)
        for (s = [-1, 1]) {
            translate([s * (gauge_l / 2 + transition_l / 2), 0, 0])
                for (x = [0 : transition_l])
                    translate([x - transition_l / 2,
                               -grip_w / 2 + s * (x - transition_l / 2) * slope,
                               0])
                        cube([1, grip_w - s * (x - transition_l / 2) * slope * 2,
                              specimen_t]);
        }
    }
}

dog_bone();
