// Flat dial ring with radial tick marks for a rotary stage
// Print orientation: flat on the bed, top face (with grooves) facing up

// ---------- Parameters ----------
outer_d      = 60;    // ring outer diameter (mm)
inner_d      = 40;    // ring inner diameter (mm)
ring_t       = 4;     // ring thickness (mm)
tick_count   = 24;    // number of radial tick marks
tick_w       = 1;     // tick groove width (mm)
tick_depth   = 1;     // tick groove depth (mm)
tick_length  = 3;     // tick groove inward length from outer edge (mm)
eps          = 0.5;   // overcut past faces to avoid coplanar surfaces (mm)

$fn = 128;

// ---------- Model ----------
difference() {
    // Main ring body
    cylinder(d = outer_d, h = ring_t);

    // Central bore
    translate([0, 0, -eps])
        cylinder(d = inner_d, h = ring_t + 2 * eps);

    // Radial tick grooves, first on +X axis
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, i * 360 / tick_count])
            translate([outer_d / 2 - tick_length, 0, ring_t - tick_depth])
                cube([tick_w, outer_d / 2 + eps, tick_depth + eps]);
    }
}
