// Ribs are centred on these parts, so rib_pitch = part length = 24 mm
// Outer rib centres at 24 mm from ends -> rib_offset = 24 mm
assert(abs(rib_pitch - plate_len / (rib_count + 1)) < 0.001, "Rib pitch inconsistent");
assert(abs(rib_offset - plate_len / (rib_count + 1)) < 0.001, "Rib offset inconsistent");

