        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred on each of the 5 equal length parts
    for (i = [0 : rib_count]) {
        x_c = -plate_len / 2 + rib_offset + i * rib_pitch;
        translate([x_c - rib_thk / 2, -plate_wid / 2, rib_z0])
