// Actually, with bottom at z = 0 and rim at z = 10, the sphere centre is at z = 5,
// so the lower hemisphere spans z = 0 .. 10 (radius 5). The user's "outer radius 10"
// must therefore be the full-diameter radius, with the bottom cut away to z = 0.
// Re-derive: full sphere radius 10, centre (0, 0, 10), lower half kept -> rim at z = 10, bottom at z = 0. OK.

// ---------- Model ----------
difference() {
    union() {
        // Hollow spherical bowl (lower half of sphere centred at z = 10)
        translate([0, 0, 10])
            difference() {
                sphere(r = sphere_r);
                translate([0, 0, -cut_extra])
                    sphere(r = sphere_r - wall);
            }
        // Flat handle, top face flush with rim (z = 10)
        translate([handle_x0, -handle_w / 2, 10 - handle_t])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }
    // Cut away the upper half (z > 10) to leave only the lower half of the sphere
    translate([0, 0, 10])
        cube([sphere_r * 2 + 2 * cut_extra, 2 * sphere_r + 2 * cut_extra, cut_extra]);
}
