// Pin hinge leaf
// Print orientation: flat plate on bed, knuckles pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 40;    // plate length along X (mm)
plate_wid   = 30;    // plate width along Y (mm)
plate_thk   = 2.5;   // plate thickness along Z (mm)

knuckle_d   = 8;     // knuckle cylinder diameter (mm)
knuckle_y   = 15;    // knuckle axis Y position (mm)
knuckle_z   = 4;     // knuckle axis height above bed (mm)
knuckle_n   = 5;     // number of segments along plate length
knuckle_sel = [1, 3, 5]; // 1-based segment indices with knuckles

pin_d       = 3;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------------- Derived ----------------
seg_len = plate_len / knuckle_n;   // 8 mm segment length
// Convert 1-based segment index to its X interval (e.g., 1 -> 0..8)
function seg_x(idx) = [idx - 1, idx] * seg_len;

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckle cylinders along X, through the plate
    for (s = knuckle_sel) {
        translate([seg_x(s)[0], knuckle_y, knuckle_z])
            rotate([0, 90, 0])
                difference() {
                    cylinder(d = knuckle_d, h = plate_len + 2 * eps);
                    // Pin hole along the knuckle axis
                    translate([seg_x(s)[0], knuckle_y, knuckle_z])
                        rotate([0, 90, 0])
                            cylinder(d = pin_d, h = plate_len + 2 * eps);
                }
    }
}
