$fn = 64;

// ---- Plate ----
plate_len   = 45;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 3;     // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;     // knuckle diameter
knuckle_n   = 3;     // number of knuckles
knuckle_w   = plate_len / knuckle_n;  // 15 mm segment width
knuckle_y   = plate_wid / 2;          // 12.5 mm axis height
knuckle_z   = plate_thk + 0.5;        // 3.5 mm axis height (overlaps plate -> fused)

// ---- Pin hole ----
pin_d       = 3;     // pin hole diameter

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st and 3rd segments, centred on their segment midpoints
        for (i = [0, 2]) {
            x_c = -plate_len / 2 + i * knuckle_w + knuckle_w / 2;
            translate([x_c, knuckle_y, 0])
                cylinder(d = knuckle_d, h = plate_thk + 1);
        }
    }

