    linear_extrude(height = plate_t)
        polygon([
            for (i = [0 : points - 1])
                for (r = [outer_r, inner_r])
                    [r * cos(2 * pi / points * i + (i % 2 ? 0 : 0)),
                     r * sin(2 * pi / points * i + (i % 2 ? 0 : 0))]
