// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness   = 3;     // specimen thickness (Z)
total_len   = 120;   // overall length along X (mm)
gauge_w     = 6;     // gauge section width (Y)
gauge_len   = 30;    // gauge section length (X)
grip_w      = 15;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
trans_len   = 10;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces (mm)

$fn = 64;

// ---------- Derived ----------
half_grip   = grip_len / 2;   // 17.5
grip_start  = half_grip - trans_len;  // 7.5
x0          = -total_len / 2;        // -60

// ---------- Model ----------
module dogbone() {
    difference() {
        // Outer profile
        linear_extrude(height = thickness)
            polygon(points = [
                // left grip
                for (s = [0 : 1])
                    [x0 - s * half_grip, -grip_w / 2 + s * grip_w / 2],
                // left transition
                for (s = [0 : 1])
                    [x0 - grip_start + s * trans_len,
                     -grip_w / 2 + s * (gauge_w - grip_w) / 2],
                // gauge section
                for (s = [0 : 1])
                    [x0 - gauge_len / 2 + s * gauge_len, -gauge_w / 2],
                // right transition
                for (s = [0 : 1])
                    [x0 + gauge_len / 2 - s * trans_len,
                     -gauge_w / 2 + s * (grip_w - gauge_w) / 2],
                // right grip
                for (s = [0 : 1])
                    [x0 + half_grip - s * grip_len / 2, -grip_w / 2 + s * grip_w / 2]
            ]);

        // Cut out grip end blocks (extends past top/bottom faces)
        for (dx = [-half_grip, half_grip])
            translate([dx > 0 ? x0 + half_grip - eps : x0 - half_grip - eps,
                       -grip_w / 2 - eps, -eps])
                cube([half_grip + eps, grip_w + 2 * eps, thickness + 2 * eps]);
    }
}

dogbone();
