    translate([-total_length / 2, -thickness / 2, 0])
        cube([total_length, thickness, thickness]);

    // Central gauge section (narrow)
    translate([-half_gauge, -gauge_width / 2, thickness + 1])
        cube([gauge_length, gauge_width, thickness + 2]);

