    for (sx = [-1, 1])
        translate([sx * outer_x, -grip_width / 2, thickness + 1])
            cube([grip_length, grip_width, thickness + 2]);

    // Transition sections: width changes linearly from grip_width to gauge_width
    for (sx = [-1, 1])
        translate([sx * (outer_x - transition_len), 0, 0])
            linear_extrude(height = thickness + 2)
                polygon([
                    [0, grip_width / 2],
                    [transition_len, gauge_width / 2]
