$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // specimen thickness (Z)
total_length   = 140;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 15;    // length of each grip-to-gauge transition (X)

// ---- Derived ----
half_gauge = gauge_length / 2;
// grip outer edge is at x = +/- (half_gauge + transition_len)
x0 = half_gauge + transition_len;

// Width at the start of a transition (grip width) and end (gauge width)
function trans_w(t) = grip_width + (8 - grip_width) * (t - grip_length) / (2 * transition_len);

difference() {
    // Union of gauge section, two grip sections, and two transition sections
    union() {
        // Gauge section
        translate([-half_gauge, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Grip sections
        for (s = [-1, 1])
            translate([s * x0 - grip_length, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);

        // Transitions
        for (s = [-1, 1])
            translate([s * (half_gauge - transition_len), -grip_width / 2, 0])
                linear_extrude(height = thickness)
                    polygon([
                        [0, grip_width / 2],
                        [transition_len, grip_width / 2],
                        [transition_len, trans_w(grip_length + transition_len)],
                        [0, -grip_width / 2],
                        [0, -trans_w(grip_length + transition_len)]
                    ]);
    }

    // Deburr overlapping faces
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx * x0 - grip_length - 0.5, sy * grip_width, 0])
            cube([1, grip_width + 1, thickness + 1]);
}
