                translate([hub_r, -spoke_width / 2, -cut_extra])
                    cube([rim_r - hub_r, spoke_width, wheel_thickness + 2 * cut_extra]);
        }
    }

    // Axle hole through centre
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = wheel_thickness + 2 * cut_extra, $fn = 64);
