difference() {
    // Truncated cone, centred on Z, resting on z = 0
    cylinder(d1 = foot_d_bottom, d2 = foot_d_top, h = foot_h);

    // Round recess in bottom face for rubber pad
    translate([0, 0, -eps])
        cylinder(d = recess_d, h = recess_depth + eps);

    // Through hole for screw along axis
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = foot_h + 2 * eps);
}
