```openscad
// Powder measuring scoop - hollow spherical bowl with a flat handle along +X
// Print orientation: bowl bottom on the bed (z = 0), handle on top, opening upward.

$fn = 96;

// ---- Bowl ----
outer_radius   = 12;   // mm, outer radius of the sphere
wall_thickness = 2;    // mm, wall thickness of the bowl
rim_z          = 12;   // mm, z of the rim (sphere centre height)
bottom_z       = 0;    // mm, z where the bowl touches the bed

// ---- Handle ----
handle_width   = 8;    // mm, handle width along Y
handle_thick   = 3;    // mm, handle thickness along Z
handle_x0      = 10;   // mm, start of handle along X
handle_x1      = 112;  // mm, end of handle along X
handle_top_z   = rim_z; // mm, z of the handle's top face (flush with rim)

// ---- Misc ----
eps            = 0.5;  // mm, overlap so cutters pass beyond faces

difference() {
    union() {
        // Lower half of a hollow sphere: outer radius R, inner radius R - t,
        // centred at (0, 0, rim_z), running from z = 0 up to the rim.
        cylinder(h = rim_z, r = outer_radius, $fn = 128);
        translate([0, 0, rim_z])
            cylinder(h = wall_thickness, r = outer_radius - wall_thickness, $fn = 128);
    }

    // Flat handle, centred on y = 0, running from x = 10 to x = 112.
    // Its bottom face sits at handle_top_z - handle_thick, so the top face
    // is flush with the rim (z = 12). The handle is embedded into the rim
    // by eps to avoid coplanar faces.
    translate([handle_x0, -handle_width / 2, handle_top_z - handle_thick])
        cube([handle_x1 - handle_x0, handle_width, handle_thick + eps]);
