// Powder measuring scoop
// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
sphere_r      = 12;    // outer radius of spherical bowl (mm)
wall          = 1.5;   // bowl wall thickness (mm)
handle_w      = 8;     // handle width in Y (mm)
handle_t      = 4;     // handle thickness in Z (mm)
handle_x0     = 10.5;  // handle start position in X (mm)
handle_x1     = 112;   // handle end position in X (mm)
cut_extra     = 0.5;   // extra length on cutting shapes to avoid coplanar faces (mm)

$fn = 96;              // curve resolution

// Derived values
rim_z      = sphere_r;     // rim height of the lower hemisphere (z = 12)
handle_z0  = rim_z - handle_t;  // handle bottom face height (z = 8)
handle_y0  = -handle_w / 2;     // handle left edge in Y
handle_y1  = handle_w / 2;      // handle right edge in Y
span_x     = handle_x1 - handle_x0;   // handle length along X

// ---------------- Model ----------------
union() {
    // Bowl: lower half of a hollow sphere, open at the top
    difference() {
        translate([0, 0, sphere_r])
            sphere(r = sphere_r);
        translate([0, 0, sphere_r - wall])
            sphere(r = sphere_r - wall);
        // keep only the lower half so the bottom touches z = 0
        translate([0, 0, -cut_extra])
            cube([2 * sphere_r, 2 * sphere_r, cut_extra]);
    }

    // Flat handle running along +X, top face flush with the rim
    translate([handle_x0, handle_y0, handle_z0])
        cube([span_x, handle_w, handle_t]);
}
