// Cable bridge - rectangular block with two semicircular tunnels along Y
// Print orientation: base on the bed (z = 0), tunnels open upward

// ---------------- Parameters ----------------
block_len    = 80;    // block length along X (mm)
block_wid    = 40;    // block width along Y (mm)
block_ht     = 12;    // block height along Z (mm)

tunnel_d     = 10;    // tunnel diameter (mm); radius = 5 mm, axis at z = 0
tunnel_count = 2;     // number of tunnels
tunnel_pitch = 16;    // centre-to-centre spacing along X (mm)

eps          = 0.5;   // overshoot so cutters pass beyond the faces (mm)
$fn          = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular tunnels: cylinder axis along Y, centred along X
    for (i = [0 : tunnel_count - 1]) {
        x = (i - (tunnel_count - 1)/2) * tunnel_pitch;
        translate([x, -block_wid/2 - eps, 0])
            rotate([-90, 0, 0])
                cylinder(d = tunnel_d, h = block_wid + 2*eps);
    }
}
