// Cabinet door pull handle
// Print orientation: posts stand on the bed (z = 0), bar on top.

$fn = 64;

// --- Posts ---
post_d      = 10;    // post diameter
post_h      = 20;    // post height (z = 0 to 20)
post_x      = 48;    // post centre X offset (+/-)
screw_d     = 3.4;   // screw hole diameter
screw_depth = 12;    // screw hole depth from bottom face

// --- Bar ---
bar_len     = 106;   // bar length along X
bar_w       = 10;    // bar width along Y
bar_t       = 8;     // bar thickness (z = 20 to 28)

// --- Misc ---
eps         = 0.5;   // cutter overshoot past faces

difference() {
    union() {
        // Posts
        for (sx = [-post_x, post_x])
            translate([sx, 0, 0])
                cylinder(d = post_d, h = post_h);

        // Bar
        translate([-bar_len / 2, -bar_w / 2, post_h])
            cube([bar_len, bar_w, bar_t]);
    }

    // Screw holes in posts, from bottom face up the axis
    for (sx = [-post_x, post_x])
        translate([sx, 0, -eps])
            cylinder(d = screw_d, h = screw_depth + eps);
}
