half_grip  = grip_length / 2;
// grip end x = -total_length/2 + half_grip ; gauge end x = -half_gauge
// check: gap = total_length - 2*half_grip - gauge_length = 2*transition_len

// ---- Model ----
difference() {
    // Outer shape: grip -> transition -> gauge -> transition -> grip
    union() {
        // Grip sections
        for (s = [-1, 1])
            translate([s * (total_length / 2 - half_grip), -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
        // Gauge section
        translate([-half_gauge, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Transitions (linear width change: grip -> gauge)
        for (s = [-1, 1]) {
            x0 = s * (total_length / 2 - half_grip);   // grip end
            x1 = s * half_gauge;                        // gauge end
            w0 = grip_width;
            w1 = gauge_width;
            // hull of two thin slabs along the transition gives a linear taper
            hull() {
                translate([x0, -w0 / 2, 0])
                    cube([1, w0, thickness + 0.01]);
                translate([x1, -w1 / 2, 0])
                    cube([1, w1, thickness + 0.01]);
            }
        }
    }
    // Optional: clean up any tiny overlapping regions at the junctions
    union() {
        for (s = [-1, 1])
            translate([s * (total_length / 2 - half_grip - 0.01), -grip_width / 2 - 0.01, 0])
                cube([grip_length + 0.02, grip_width + 0.02, thickness + 0.01]);
        translate([-half_gauge - 0.01, -gauge_width / 2 - 0.01, 0])
            cube([gauge_length + 0.02, gauge_width + 0.02, thickness + 0.01]);
    }
}
