// ---------- Parameters ----------
thickness   = 4;     // specimen thickness (Z)
total_len   = 130;   // overall length along X
gauge_w     = 6;     // gauge section width (Y)
gauge_len   = 30;    // gauge section length (X)
grip_w      = 20;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
trans_len   = 15;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_grip   = grip_w / 2;
half_gauge  = gauge_w / 2;
reach       = grip_len + trans_len;   // distance from origin to grip end
area        = gauge_w * thickness;    // gauge cross-section area

// ---------- Model ----------
difference() {
    // Outer solid
    hull() {
        // Grip end (right)
        translate([reach, -half_grip, 0])
            cube([grip_len, grip_w, thickness]);
        // Grip end (left)
        translate([-reach, -half_grip, 0])
            cube([grip_len, grip_w, thickness]);
    }

    // Central groove, overcut into the grips to avoid coplanar faces
    translate([-gauge_len / 2, -half_gauge - eps, -eps])
        cube([gauge_len, gauge_w + 2 * eps, thickness + 2 * eps]);
}
