```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // length of each grip-gauge transition (X)

// ---- Derived ----
half_gauge = gauge_length / 2;
// grip outer edge is at x = +/- (half_gauge + transition_len)
x0 = half_gauge + transition_len;   // grip start / gauge end X

// Width at a given X (linear interpolation between grip and gauge)
function width_at(x) =
    if (x < -x0) grip_width
    else if (x > x0) grip_width
    else if (x < 0) gauge_width + (x / transition_len) * (grip_width - gauge_width)
    else gauge_width + ((x - transition_len) / transition_len) * (grip_width - gauge_width);

difference() {
    // Main body
    translate([-total_length / 2, -thickness / 2, 0])
        linear_extrude(thickness)
            polygon([for (sx = [-1, 1]) for (y = [-thickness / 2 : thickness / 2])
                [sx * total_length / 2, y]]);

    // Cut out the dog-bone shape, keeping a thin shell
    translate([-total_length / 2 - 1, -thickness / 2 - 1, -1])
        linear_extrude(thickness + 2)
            polygon([for (sx = [-1, 1])
                concat([sx * x0, -thickness / 2],
                       [for (x = [-x0 : transition_len : x0])
                           [sx * x, width_at(x) / 2],
                       [sx * (total_length / 2 - transition_len), thickness / 2]]));
}
